INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_16_m_16_2_66',
  'Which AWS service is used to manage the desired instance count and scaling policies for a SageMaker endpoint to handle fluctuating inference traffic?',
