INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_17_m_17_1_80',
  'What is the primary benefit of detecting and responding to model drift (concept drift, data drift) in production?',
  'mcq',
  '["To reduce the cost of inference endpoints.","To ensure the model continues to provide accurate and reliable predictions over time.","To simplify the deployment process for new model versions.","To prevent unauthorized access to the model endpoint."]'::json,
  '{1}',
  'Option B (To ensure the model continues to provide accurate and reliable predictions over time) is the primary benefit. Model drift indicates that the model''s performance is degrading because the data it sees in production or the underlying relationships have changed. Detecting and responding to this drift (e.g., through retraining) is crucial for maintaining the model''s effectiveness. Option A (To reduce cost) is a separate optimization. Option C (To simplify deployment) is unrelated. Option D (To prevent unauthorized access) is a security concern.',
  NOW(),
  'quiz_domain17_3',
  NOW(),
  67,
  NULL,
  NULL,
  'm_17_1',
  'medium'
) ON CONFLICT (id) DO NOTHING;

