INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_17_m_17_1_84',
  'Which type of monitoring is essential to detect when the relationship between input features and the target variable changes over time, impacting model accuracy?',
