INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_14_m_14_2_101',
  'To prevent training-serving skew, which SageMaker services can help ensure consistent feature computation between training and production? (Select TWO.)',
  'multiple',
  '["Amazon SageMaker Feature Store","Amazon SageMaker Pipelines","Amazon SageMaker Ground Truth","Amazon SageMaker Clarify","Amazon SageMaker Data Wrangler"]'::json,
  '{0,1}',
  'Option A (Amazon SageMaker Feature Store) is designed to store and manage features, ensuring that the same feature definitions and transformations are used consistently across training and inference. Option B (Amazon SageMaker Pipelines) allows you to define and orchestrate end-to-end ML workflows, which can include consistent feature engineering steps applied to both training and inference data. This directly addresses anti-pattern ap-1.2-002. Option C (Amazon SageMaker Ground Truth) is for data labeling. Option D (Amazon SageMaker Clarify) is for bias detection. Option E (Amazon SageMaker Data Wrangler) is for data preparation, but Feature Store and Pipelines are key for consistency across the lifecycle.',
  NOW(),
  'quiz_domain14_3',
  NOW(),
  40,
  NULL,
  NULL,
  'm_14_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
