INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_14_m_14_3_119',
  'When preparing time-series data for machine learning, which data splitting strategies are appropriate to avoid data leakage? (Select TWO.)',
  'multiple',
  '["Random split","Stratified split","Time-series split","Chronological split","K-fold cross-validation"]'::json,
  '{2,3}',
  'Option C (Time-series split) and Option D (Chronological split) are appropriate strategies for time-series data. They ensure that training data always precedes validation and test data chronologically, preventing future data from leaking into the training set (anti-pattern ap-1.3-001). Option A (Random split) is generally unsuitable for time-series data as it can introduce future information into the training set. Option B (Stratified split) is used for maintaining class proportions, typically for classification problems. Option E (K-fold cross-validation) is also generally not recommended for time-series data in its standard form due to the temporal dependency.',
  NOW(),
  'quiz_domain14_3',
  NOW(),
  70,
  NULL,
  NULL,
  'm_14_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

