INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_14_m_14_3_128',
  'Which of the following are anti-patterns related to data splitting for machine learning models? (Select TWO.)',
  'multiple',
  '["Using stratified splits for imbalanced classification","Using random splits for time-series data","Fitting scalers only on training data","Applying normalization after the train-test split on the entire dataset","Using chronological splits for time-series data"]'::json,
  '{1,3}',
  'Option B (Using random splits for time-series data) is an anti-pattern (ap-1.3-001) because it can lead to data leakage, where future information is present in the training set, resulting in overly optimistic model evaluation. Option D (Applying normalization after the train-test split on the entire dataset) is an anti-pattern (ap-1.2-001) because fitting scalers on the full dataset (including test data) causes data leakage; scalers should only be fitted on the training data. Option A (Using stratified splits for imbalanced classification) and Option E (Using chronological splits for time-series data) are best practices. Option C (Fitting scalers only on training data) is a best practice.',
  NOW(),
  'quiz_domain14_3',
  NOW(),
  79,
  NULL,
  NULL,
  'm_14_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

