INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_15_m_15_3_98',
  'A data scientist observes that their model performs exceptionally well on the training data but poorly on unseen validation data. Which two techniques should they consider first to address this issue? (Select TWO.)',
