INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_16_m_16_2_122',
  'A data science team needs to deploy a custom ML model on Amazon SageMaker. Arrange the following steps in the correct order to containerize the model and push it to Amazon ECR.',
  'ordering',
