INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_16_m_16_2_145',
  'A machine learning team needs to establish governance for their models by registering a new model version in Amazon SageMaker Model Registry. Order the steps required to register a model.',
  'ordering',
  '["Approve or reject the model version for deployment.","Create a model package group in SageMaker Model Registry.","Register the model as a new model package version within the group.","Train and evaluate the machine learning model."]'::json,
  '{3,1,2,0}',
  'Option D (Train and evaluate the machine learning model) is the initial step, as a model must exist and be evaluated before it can be registered. Option B (Create a model package group in SageMaker Model Registry) provides the logical container for model versions. Option C (Register the model as a new model package version within the group) adds the specific model artifact and metadata to the registry. Finally, Option A (Approve or reject the model version for deployment) is a governance step that determines if the model can be used in production, often involving a manual or automated review.',
  NOW(),
  'quiz_domain16_3',
  NOW(),
  24,
  NULL,
  NULL,
  'm_16_2',
  'medium'
) ON CONFLICT (id) DO NOTHING;

