INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_17_m_17_1_125',
  'Order the steps to integrate SageMaker Model Monitor with Amazon CloudWatch Alarms for automated alerts.',
  'ordering',
  '["Create a CloudWatch Alarm based on a Model Monitor metric.","Configure SageMaker Model Monitor to publish metrics to CloudWatch.","Define the alarm''s threshold and notification actions.","Set up a SageMaker Model Monitor schedule."]'::json,
  '{3,1,0,2}'::int[],
  'To generate metrics for monitoring, you must first have Model Monitor running. Option D (Set up a SageMaker Model Monitor schedule) initiates the monitoring process. Once monitoring is active, Option B (Configure SageMaker Model Monitor to publish metrics to CloudWatch) ensures the data is available for alarms. With metrics in CloudWatch, Option A (Create a CloudWatch Alarm based on a Model Monitor metric) can be established. Finally, Option C (Define the alarm''s threshold and notification actions) specifies when and how to alert.',
  NOW(),
  'quiz_domain17_3',
  NOW(),
  25,
  NULL,
  NULL,
  'm_17_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
