INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_17_m_17_1_142',
  'A team wants to ensure their model''s predictions remain unbiased over time. Order the steps to set up bias drift monitoring using SageMaker Model Monitor.',
  'ordering',
