INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_14_m_14_1_176',
  'Match Amazon SageMaker data input modes to their characteristics for training jobs.',
  'matching',
  '{"A":"File mode","B":"Pipe mode","C":"FastFile mode"}'::json,
  NULL,
  'The correct pairings are: ''File mode'' with ''Downloads full dataset'', ''Pipe mode'' with ''Streams data on demand'', and ''FastFile mode'' with ''Streams data faster''. File mode downloads the entire dataset from Amazon S3 to the training instance before training begins. Pipe mode streams data directly from S3 to the training instance during training, reducing startup time. FastFile mode is an enhanced version of Pipe mode that uses optimized S3 access for even faster data streaming.',
  NOW(),
  'quiz_domain14_3',
  NOW(),
  18,
  '{"left":["File mode","Pipe mode","FastFile mode"],"right":["Streams data faster","Downloads full dataset","Streams data on demand"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_14_1',
  'hard'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
