INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_14_m_14_1_178',
  'Match common data storage and ingestion anti-patterns to their recommended best practices for ML.',
  'matching',
  '{"A":"CSV for large analytics","B":"File mode for large training","C":"Relational DB for raw lake"}'::json,
  NULL,
  'The correct pairings are: ''CSV for large analytics'' with ''Use Parquet/ORC'', ''File mode for large training'' with ''Use Pipe/FastFile mode'', and ''Relational DB for raw lake'' with ''Use Amazon S3''. Using row-based CSV for large-scale analytics is inefficient; columnar formats like Parquet or ORC are better. File mode for large SageMaker training jobs can cause significant latency due to full dataset downloads; Pipe or FastFile mode is preferred for streaming. Using a relational database for raw data lake storage is not cost-effective or scalable; Amazon S3 is the ideal choice.',
  NOW(),
  'quiz_domain14_3',
  NOW(),
  20,
  '{"left":["CSV for large analytics","File mode for large training","Relational DB for raw lake"],"right":["Use Pipe/FastFile mode","Use Amazon S3","Use Parquet/ORC"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_14_1',
  'hard'
) ON CONFLICT (id) DO NOTHING;

