INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_14_m_14_2_145',
  'Match each feature engineering technique to its primary purpose.',
  'matching',
  '{"A":"Normalization","B":"One-hot encoding","C":"Binning"}'::json,
  NULL,
  'Normalization (Option A) scales numerical features to a standard range, typically between 0 and 1 or with a mean of 0 and standard deviation of 1, which helps algorithms converge faster. One-hot encoding (Option B) transforms categorical variables into a numerical format by creating binary columns for each category, preventing ordinal relationships from being implied. Binning (Option C) converts continuous numerical values into discrete intervals or bins, which can help reduce noise and improve model robustness.',
  NOW(),
  'quiz_domain14_3',
  NOW(),
  29,
  '{"left":["Normalization","One-hot encoding","Binning"],"right":["Scales numerical features to a standard range","Converts categorical variables into a numerical format","Groups continuous numerical values into discrete intervals"]}'::json,
