) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_14_m_14_2_146',
  'Match the strategy for handling missing data to its description.',
  'matching',
  '{"A":"Imputation","B":"Dropping","C":"Mean/Median substitution"}'::json,
  NULL,
  'Imputation (Option A) is the process of filling in missing values with estimated data, which can be done using various statistical or machine learning techniques. Dropping (Option B) involves removing entire rows or columns that contain missing values, a simple but potentially data-lossy approach. Mean/Median substitution (Option C) is a common imputation method where missing numerical values are replaced by the mean or median of the respective feature.',
  NOW(),
  'quiz_domain14_3',
  NOW(),
  30,
  '{"left":["Imputation","Dropping","Mean/Median substitution"],"right":["Filling in missing values with estimated data","Removing rows or columns with missing values","Replacing missing values with the average or middle value"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
