  'm_15_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_15_m_15_3_141',
  'Match each Amazon SageMaker Clarify feature to its purpose.',
  'matching',
  '{"A":"SageMaker Clarify","B":"Bias Detection","C":"Feature Attribution"}'::json,
  NULL,
  'SageMaker Clarify is a service that provides tools for detecting potential bias in machine learning models and data, and for explaining model predictions. Bias Detection is the process of identifying systematic unfairness in data or model outputs. Feature Attribution explains the contribution of each input feature to a model''s prediction, enhancing model interpretability.',
