) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_15_m_15_3_142',
  'Match each model performance issue to a common cause.',
  'matching',
  '{"A":"Overfitting","B":"Underfitting","C":"High Variance"}'::json,
  NULL,
  'Overfitting typically occurs when a model is excessively complex relative to the amount or noise in the training data. Underfitting is often a result of a model being too simple to learn the underlying relationships. High Variance indicates that a model is too sensitive to the specific training data it sees, leading to large fluctuations in performance on different datasets.',
  NOW(),
  'quiz_domain15_3',
  NOW(),
