INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_16_m_16_1_156',
  'Match the SageMaker inference type to the latency requirement it satisfies.',
  'matching',
  '{"A":"Real-time inference","B":"Batch Transform","C":"Asynchronous inference"}'::json,
  NULL,
  'Amazon SageMaker Real-time inference (Option A) is designed for immediate, low-latency predictions. Amazon SageMaker Batch Transform (Option B) is for offline processing of large datasets, which typically has high latency. Amazon SageMaker Asynchronous Inference (Option C) is suitable for requests with larger payloads or longer processing times, where predictions are queued and returned later, resulting in medium latency.',
  NOW(),
  'quiz_domain16_3',
  NOW(),
