INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_16_m_16_3_129',
  'Match the automated retraining trigger to its description.',
  'matching',
  '{"A":"Schedule-based trigger","B":"Data drift trigger","C":"Performance degradation trigger"}'::json,
  NULL,
  'A schedule-based trigger (Option A) initiates retraining at predefined time intervals, regardless of model performance or data changes. A data drift trigger (Option B) automatically starts retraining when significant changes are detected in the input data distribution. A performance degradation trigger (Option C) initiates retraining when the model''s performance metrics (e.g., accuracy, F1-score) fall below a predefined threshold.',
  NOW(),
  'quiz_domain16_3',
  NOW(),
  53,
  '{"left":["Schedule-based trigger","Data drift trigger","Performance degradation trigger"],"right":["Retrains at set intervals","Retrains on input data changes","Retrains on model accuracy drop"]}'::json,
