) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_16_m_16_3_130',
  'Match the model deployment strategy to its characteristic for risk management.',
  'matching',
  '{"A":"Canary release","B":"Blue/green deployment","C":"Direct 100% rollout"}'::json,
  NULL,
  'A canary release (Option A) involves gradually shifting a small percentage of live traffic to the new model version, allowing for real-world testing before full rollout. Blue/green deployment (Option B) involves running two identical production environments (blue and green) and switching traffic entirely to the new ''green'' version once validated, enabling zero-downtime updates. A direct 100% rollout (Option C) immediately replaces the old model with the new one for all traffic, carrying a high risk of production outages if the new model has issues.',
  NOW(),
  'quiz_domain16_3',
  NOW(),
  54,
  '{"left":["Canary release","Blue/green deployment","Direct 100% rollout"],"right":["Gradual traffic shift","Zero-downtime environment swap","High risk of production issues"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_16_3',
  'medium'
) ON CONFLICT (id) DO NOTHING;

