INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_16_m_16_3_134',
  'Match the CI/CD for ML component to its core responsibility.',
  'matching',
  '{"A":"AWS CodePipeline","B":"AWS CodeBuild","C":"Amazon SageMaker Model Registry"}'::json,
  NULL,
  'AWS CodePipeline (Option A) is responsible for automating the entire release process, from source code changes to deployment. AWS CodeBuild (Option B) focuses on compiling source code, running tests, and producing build artifacts. Amazon SageMaker Model Registry (Option C) provides a centralized repository for managing, versioning, and approving ML models, ensuring governance and traceability.',
  NOW(),
  'quiz_domain16_3',
  NOW(),
  58,
  '{"left":["AWS CodePipeline","AWS CodeBuild","Amazon SageMaker Model Registry"],"right":["Automates release process","Compiles and tests code","Manages model versions"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_16_3',
  'medium'
