INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_17_m_17_2_145',
  'Match each AWS service to its primary function in monitoring and cost management.',
  'matching',
  '{"A":"Amazon CloudWatch","B":"AWS Cost Explorer","C":"Amazon CloudWatch Alarms"}'::json,
  NULL,
  'Amazon CloudWatch (Option A) is a monitoring and observability service that collects monitoring and operational data in the form of logs, metrics, and events. AWS Cost Explorer (Option B) is a tool that enables you to visualize, understand, and manage your AWS costs and usage over time. Amazon CloudWatch Alarms (Option C) allow you to watch a single metric or the result of a math expression based on that metric and to perform one or more actions based on the value of the metric or expression relative to a threshold over a number of time periods.',
  NOW(),
  'quiz_domain17_3',
  NOW(),
  1,
  '{"left":["Amazon CloudWatch","AWS Cost Explorer","Amazon CloudWatch Alarms"],"right":["Collects monitoring data","Triggers actions on metrics","Visualizes and manages costs"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_17_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
