INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_17_m_17_1_143',
  'Match each type of model drift to its characteristic.',
  'matching',
  '{"A":"Data Drift","B":"Concept Drift","C":"Bias Drift"}'::json,
  NULL,
  'Data Drift (Option A) refers to a change in the distribution of the input data used by the model. Concept Drift (Option B) occurs when the relationship between the input features and the target variable changes over time. Bias Drift (Option C) indicates a change in the fairness of the model''s predictions, potentially leading to discriminatory outcomes.',
  NOW(),
  'quiz_domain17_3',
  NOW(),
  23,
  '{"left":["Data Drift","Concept Drift","Bias Drift"],"right":["Change in input data distribution","Change in target variable relationship","Change in model fairness over time"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_17_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
