INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_17_m_17_1_154',
  'Upon detecting model drift, an ML engineer needs to initiate a response. Match the drift type to a common response strategy.',
  'matching',
  '{"A":"Data drift","B":"Model quality degradation"}'::json,
  NULL,
  'When ''Data drift'' (left item 0) is detected, meaning the input data distribution has changed, a common response is to ''Retrain with new data'' (right item 0) that reflects the current distribution. If ''Model quality degradation'' (left item 1) is observed, indicating a drop in performance metrics, the appropriate response is often to ''Investigate model issues'' (right item 1), which might involve hyperparameter tuning, feature engineering, or even a different model architecture.',
  NOW(),
  'quiz_domain17_3',
